const item = $input.first();
const body = item.json.body || {};
if (String(body.consentement).toLowerCase() !== 'true') {
  throw new Error("Consentement manquant : l'étudiant doit accepter l'analyse de ses documents.");
}
const aides = Array.isArray(body.aides)
  ? body.aides
  : String(body.aides || 'apl').split(',').map(a => a.trim()).filter(Boolean);
const photos = [];
for (const [cle, fichier] of Object.entries(item.binary || {})) {
  const buffer = await this.helpers.getBinaryDataBuffer(0, cle);
  photos.push({ nom_fichier: fichier.fileName || cle, mime: fichier.mimeType || 'image/png', base64: buffer.toString('base64') });
}
if (photos.length === 0) throw new Error('Aucune photo reçue.');
const nombre = v => (v === undefined || v === null || v === '' || isNaN(Number(v))) ? null : Number(v);
const boursier = body.boursier === undefined || body.boursier === '' ? null : String(body.boursier).toLowerCase() === 'true';
return [{ json: {
  email: body.email || null, prenom: body.prenom, nom: body.nom, aides,
  ressources_12_mois: nombre(body.ressources_12_mois), boursier,
  consentement_analyse: true, consentement_le: new Date().toISOString(), photos,
} }];

const p = $input.first().json;
return [{ json: { nom: p.nom, prenom: p.prenom, email: p.email,
  ressources_12_mois: p.ressources_12_mois, boursier: p.boursier,
  consentement_analyse: p.consentement_analyse, consentement_le: p.consentement_le } }];

const PROMPT = "Tu lis la photo d'un document administratif d'étudiant (jeu de test fictif). Réponds UNIQUEMENT avec un objet JSON de la forme {\"type\": \"...\", \"champs\": {...}}, sans texte autour. type est l'un de : piece_identite, bail, certificat_scolarite, avis_imposition, fiche_paie, quittance_loyer, contrat_alternance, autre. Champs à extraire selon le type : piece_identite : nom, prenom, sexe, nationalite, date_naissance, lieu_naissance, numero_document, date_expiration ; bail : bailleur, adresse_bailleur, locataire, adresse_logement, type_logement, meuble (true ou false), colocation (true ou false, null si impossible à savoir), nombre_occupants, surface_m2, loyer_hors_charges, charges, date_debut, duree ; certificat_scolarite : etablissement, academie, nom, prenom, date_naissance, ine, formation, annee_universitaire, date_emission ; avis_imposition : annee_revenus, annee_avis, declarants, adresse, nombre_parts, revenu_brut_global, revenu_fiscal_reference, impot_net ; fiche_paie : employeur, siret_employeur, adresse_employeur, salarie, periode, heures, salaire_brut, net_social, net_a_payer ; quittance_loyer : bailleur, locataire, adresse_logement, periode, loyer_hors_charges, charges, total, date ; contrat_alternance (contrat d'apprentissage ou de professionnalisation, CERFA) : type_contrat, employeur, siret_employeur, adresse_employeur, salarie, cfa, date_debut, date_fin, remuneration_brute. Précisions : ine = identifiant national étudiant (11 caractères) ; academie = nom de l'académie ; surface_m2 = surface habitable en m², nombre seul ; siret_employeur = 14 chiffres sans espaces ; net_social = le montant « net social » de la fiche de paie, différent du net à payer ; cfa = nom du centre de formation ou de l'école. Dates au format JJ/MM/AAAA, périodes au format MM/AAAA, montants et surfaces en nombres sans symbole. Recopie les noms exactement comme écrits, même s'ils semblent faux. Si un champ est absent ou illisible, mets null.";
const prep = $('Vérifier et préparer').first().json;
const etudiant = $input.first().json;
return prep.photos.map(p => ({ json: {
  etudiant_id: etudiant.id,
  nom_fichier: p.nom_fichier,
  requete_hf: {
    model: 'Qwen/Qwen3.8-27B',
    temperature: 0,
    messages: [{ role: 'user', content: [
      { type: 'text', text: PROMPT },
      { type: 'image_url', image_url: { url: `data:${p.mime};base64,${p.base64}` } },
    ] }],
  },
} }));

const TYPES = ['piece_identite', 'bail', 'certificat_scolarite', 'avis_imposition', 'fiche_paie', 'quittance_loyer', 'contrat_alternance', 'autre'];
const photos = $('Découper les photos').all();
return $input.all().map((item, i) => {
  const texte = item.json.choices?.[0]?.message?.content ?? '';
  let lu;
  try { lu = JSON.parse(texte.replace(/```json|```/g, '').trim()); }
  catch (e) { lu = { type: 'autre', champs: {}, erreur_lecture: texte.slice(0, 500) }; }
  const photo = photos[i].json;
  return { json: {
    etudiant_id: photo.etudiant_id,
    ref_jeu_de_test: photo.nom_fichier,
    type: TYPES.includes(lu.type) ? lu.type : 'autre',
    champs_extraits: lu.champs || {},
    statut: lu.erreur_lecture ? 'erreur' : 'extrait',
    modele: 'Qwen/Qwen3.8-27B',
  } };
});

const PROMPT = "Tu vérifies la cohérence du dossier d'un étudiant. Année universitaire en cours : 2026-2027. Voici les documents extraits (JSON). Compare-les entre eux et signale seulement les VRAIS problèmes. Sois tolérant : les documents viennent de sources différentes et sont lus par photo. \n\nNE SIGNALE JAMAIS : une différence de majuscules ou minuscules (MARTIN = Martin), d'accents (Léa = LEA), de tirets ou d'espaces (Jean-Pierre = Jean Pierre), d'ordre nom / prénom, un deuxième prénom en plus ou en moins, un nom d'usage ou d'épouse ; pour les adresses : abréviations (bd = boulevard, av = avenue, r = rue, st = saint), ponctuation, compléments (bâtiment, étage, porte, appartement, résidence), ordre des éléments, ville écrite avec ou sans arrondissement ; un format de date différent ; un champ illisible ou vide (null). Les parents sur l'avis d'imposition peuvent avoir un autre prénom et une autre adresse que l'étudiant : c'est normal.\n\nCodes possibles : nom_incoherent (UNIQUEMENT si le nom de famille est clairement celui d'une autre personne), adresse_incoherente (UNIQUEMENT si la rue ou le code postal du logement sont différents entre bail et quittance), annee_avis_incorrecte (avis d'imposition plus ancien que l'avis 2025 sur les revenus 2024), certificat_perime (année universitaire autre que 2026-2027), montants_incoherents (par exemple net supérieur au brut, total différent de loyer + charges de plus de 5 €). Gravité : bloquante seulement pour certificat_perime, un document qui appartient à une autre personne de façon évidente, ou des montants impossibles ; tout le reste et tout doute = a_verifier. Réponds UNIQUEMENT avec un objet JSON {\"anomalies\": [{\"code\": \"...\", \"type_document\": \"...\", \"message\": \"phrase courte, en tutoyant l'étudiant\", \"gravite\": \"bloquante\" ou \"a_verifier\"}]}. S'il n'y a aucun problème, réponds {\"anomalies\": []}.";
const docs = $input.all().map(i => i.json);
const documents = docs.map(d => ({ id: d.id, type: d.type, champs: d.champs_extraits }));
return [{ json: {
  etudiant_id: docs[0].etudiant_id,
  documents,
  requete_hf: {
    model: 'Qwen/Qwen3.8-27B',
    temperature: 0,
    messages: [
      { role: 'system', content: PROMPT },
      { role: 'user', content: JSON.stringify(documents) },
    ],
  },
} }];

const regroupe = $('Regrouper les documents').first().json;
const texte = $input.first().json.choices?.[0]?.message?.content ?? '';
let anomalies = [];
try { anomalies = JSON.parse(texte.replace(/```json|```/g, '').trim()).anomalies || []; }
catch (e) {
  anomalies = [{ code: 'controle_illisible', type_document: null, gravite: 'a_verifier',
                 message: "Le contrôle automatique n'a pas pu être lu : à vérifier à la main." }];
}

// ---- Vérification par code : on ne garde pas les faux problèmes (majuscules, accents, abréviations…). ----
const docs = regroupe.documents || [];
const champs = t => (docs.find(d => d.type === t) || {}).champs || {};
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const VIDES = new Set(['de', 'du', 'des', 'la', 'le', 'les', 'l', 'd', 'et', 'epouse', 'ep', 'nee', 'ne', 'mme', 'm', 'mr', 'mlle']);
const mots = s => norm(s).split(' ').filter(m => m.length >= 2 && !VIDES.has(m));

// Noms : on compare les noms de famille, sans tenir compte des majuscules, accents, tirets ni de l'ordre.
const id = champs('piece_identite');
const certif = champs('certificat_scolarite');
// Référence : la pièce d'identité ; le certificat seulement s'il n'y a pas de pièce d'identité.
const nomsRef = new Set(mots(id.nom).length ? mots(id.nom) : mots(certif.nom));
const nomsDuDoc = t => {
  const c = champs(t);
  return mots([c.nom, c.prenom, c.locataire, c.salarie, c.declarants].filter(Boolean).join(' '));
};
const memeNom = t => {
  if (nomsRef.size === 0) return true;
  const m = nomsDuDoc(t);
  if (m.length === 0) return true; // nom illisible : pas une incohérence
  return m.some(x => nomsRef.has(x));
};

// Adresses du logement : code postal + mots de la rue, abréviations développées, compléments ignorés.
const ABR = { bd: 'boulevard', bld: 'boulevard', boul: 'boulevard', av: 'avenue', ave: 'avenue', r: 'rue', st: 'saint', ste: 'sainte', pl: 'place', imp: 'impasse', all: 'allee', ch: 'chemin', rte: 'route', fg: 'faubourg', fbg: 'faubourg', qu: 'quai', crs: 'cours', sq: 'square' };
const COMPLEMENTS = new Set(['bat', 'batiment', 'etage', 'porte', 'appartement', 'appt', 'apt', 'app', 'residence', 'res', 'gauche', 'droite', 'escalier', 'esc', 'er', 'e', 'eme', 'ieme', 'n', 'no', 'numero', 'paris', 'lyon', 'marseille', 'france', 'cedex', 'arrondissement']);
const adresse = s => {
  const n = norm(s);
  const cp = (n.match(/\b\d{5}\b/) || [])[0] || null;
  const rue = n.split(' ').map(m => ABR[m] || m).filter(m => m.length >= 3 && !/^\d+$/.test(m) && !COMPLEMENTS.has(m) && !VIDES.has(m));
  return { cp, rue };
};
const adressesProches = (a, b) => {
  if (!a || !b) return true;
  const x = adresse(a), y = adresse(b);
  if (x.cp && y.cp && x.cp !== y.cp) return false;
  if (x.rue.length === 0 || y.rue.length === 0) return true;
  return x.rue.some(m => y.rue.includes(m));
};
const bail = champs('bail').adresse_logement;
const autresAdresses = [champs('quittance_loyer').adresse_logement].filter(Boolean);
const DOCS_LOGEMENT = ['bail', 'quittance_loyer'];

// Année universitaire : acceptée si elle couvre 2026-2027 (« 2026/2027 », « 2026-2028 » pour un cursus sur 2 ans, « 26-27 »…).
const anneeOk = s => {
  const ans = (String(s || '').match(/\d{2,4}/g) || []).map(x => (x.length === 2 ? 2000 + Number(x) : Number(x))).filter(a => a >= 2000 && a <= 2100);
  if (ans.length === 0) return true; // illisible : pas une raison de bloquer
  const debut = Math.min(...ans), fin = Math.max(...ans);
  return debut <= 2026 && fin >= 2026;
};

// Seules ces raisons peuvent bloquer ; tout le reste est à vérifier.
const BLOQUANTS = new Set(['certificat_perime', 'montants_incoherents']);

anomalies = anomalies.flatMap(a => {
  const code = String(a.code || '');
  if (code === 'nom_incoherent') {
    if (memeNom(a.type_document)) return [];
    return [{ ...a, gravite: 'a_verifier' }];
  }
  if (code === 'adresse_incoherente') {
    // Adresse d'un employeur ou d'une école : pas une incohérence du dossier logement.
    if (a.type_document && !DOCS_LOGEMENT.includes(a.type_document)) return [];
    if (autresAdresses.every(x => adressesProches(bail, x))) return [];
    return [{ ...a, gravite: 'a_verifier' }];
  }
  if (code === 'certificat_perime' || /annee/.test(code) && (a.type_document === 'certificat_scolarite' || !a.type_document)) {
    if (code !== 'annee_avis_incorrecte' && anneeOk(certif.annee_universitaire)) return [];
  }
  if (!BLOQUANTS.has(code)) return [{ ...a, gravite: 'a_verifier' }];
  return [a];
});

return [{ json: { etudiant_id: regroupe.etudiant_id, documents: regroupe.documents, anomalies, nb_anomalies: anomalies.length } }];

const { etudiant_id, documents } = $('Lire les anomalies').first().json;
const doc = t => (documents.find(d => d.type === t) || {}).champs || {};
const versDate = s => {
  const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(String(s || ''));
  return m ? `${m[3]}-${m[2]}-${m[1]}` : null;
};
const nombre = v => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const id = doc('piece_identite');
const certif = doc('certificat_scolarite');
const bail = doc('bail');
const travaille = documents.some(d => d.type === 'fiche_paie');
return [{ json: {
  etudiant_id,
  nom: id.nom, prenom: id.prenom, date_naissance: versDate(id.date_naissance), nationalite: id.nationalite,
  etablissement: certif.etablissement, formation: certif.formation,
  adresse_logement: bail.adresse_logement, type_logement: bail.type_logement,
  loyer_hors_charges: nombre(bail.loyer_hors_charges), charges: nombre(bail.charges),
  situation_pro: travaille ? 'salarié(e) ou alternant(e)' : 'aucune',
  updated_at: new Date().toISOString(),
} }];

const { documents, anomalies } = $input.first().json;
const ANCIEN = { annee_avis_incorrecte: 'avis_imposition', certificat_perime: 'certificat_scolarite' };
return documents.map(d => {
  const siennes = anomalies
    .filter(a => (a.type_document || ANCIEN[a.code]) === d.type)
    .map(a => ({ code: a.code, message: a.message, gravite: a.gravite === 'bloquante' ? 'bloquante' : 'a_verifier' }));
  return { json: {
    id: d.id,
    anomalies: siennes,
    statut: siennes.some(a => a.gravite === 'bloquante') ? 'rejete' : 'verifie',
  } };
});

// Moteur d'éligibilité : profil + documents + catalogue → une démarche proposée par aide.
const p = $('Construire le profil').first().json;
const docs = $('Lire les anomalies').first().json.documents;
const aides = $input.all().map(i => i.json);

const types = new Set(docs.map(d => d.type));
const naissance = p.date_naissance ? new Date(p.date_naissance) : null;
const age = naissance ? Math.floor((Date.now() - naissance.getTime()) / (365.25 * 24 * 3600 * 1000)) : null;
const sansAccent = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const NATIONALITES_EEE = ['francais', 'allemand', 'italien', 'espagnol', 'portugais', 'belge', 'neerlandais', 'luxembourgeois',
  'irlandais', 'autrichien', 'grec', 'finlandais', 'suedois', 'danois', 'polonais', 'tcheque', 'slovaque', 'hongrois',
  'roumain', 'bulgare', 'croate', 'slovene', 'estonien', 'letton', 'lituanien', 'maltais', 'chypriote', 'norvegien',
  'islandais', 'liechtensteinois'];
const nat = sansAccent(p.nationalite);
const eee = NATIONALITES_EEE.some(n => nat.includes(n));
const locataire = types.has('bail');
const alternant = /altern|apprenti/i.test(p.formation || '');
const nets = docs.filter(d => d.type === 'fiche_paie').map(d => Number(d.champs?.net_a_payer) || 0);
const netMoyen = nets.length ? nets.reduce((a, b) => a + b, 0) / nets.length : 0;
const SEUIL_PRIME = 1155; // environ 78 % du Smic net depuis juin 2026 : à confirmer sur caf.fr

function evaluer(aide) {
  switch (aide.code) {
    case 'apl':
      if (!locataire) return ['non_concerne', "Aucun bail dans tes documents."];
      if (p.nationalite && !eee) return ['peut_etre', "Hors UE : depuis le 1er juillet 2026, l'APL n'est possible que si tu es boursier."];
      return ['eligible', "Tu es locataire : la CAF peut t'aider à payer ton loyer."];
    case 'visale':
      return locataire && (age === null || age <= 30) ? ['eligible', 'Tu es étudiant et locataire : Visale peut se porter garant.']
                                                      : ['peut_etre', aide.conditions];
    case 'loca_pass':
      return locataire ? ['peut_etre', 'Si tu es salarié, alternant ou boursier et que tu dois verser un dépôt de garantie.'] : ['non_concerne', 'Aucun bail dans tes documents.'];
    case 'mobili_jeune':
      if (alternant && locataire && (age === null || age < 30)) return ['eligible', 'Tu es en alternance, locataire et tu as moins de 30 ans.'];
      return alternant ? ['peut_etre', aide.conditions] : ['non_concerne', "Réservée aux alternants."];
    case 'prime_activite':
      if (netMoyen >= SEUIL_PRIME) return ['eligible', `Ton salaire moyen (${Math.round(netMoyen)} €) dépasse le seuil d'environ 78 % du Smic.`];
      return nets.length ? ['peut_etre', 'Ton salaire semble sous le seuil : la simulation CAF tranchera.']
                         : ['non_concerne', 'Aucune fiche de paie dans tes documents.'];
    case 'pret_garanti':
      if (age !== null && age >= 18 && age < 28 && eee) return ['eligible', 'Tu as moins de 28 ans et la nationalité requise.'];
      return age === null || !p.nationalite ? ['peut_etre', aide.conditions] : ['non_concerne', aide.conditions];
    case 'bourse_crous':
      return types.has('avis_imposition') ? ['peut_etre', "Le simulateur du Crous donnera ton échelon à partir de l'avis d'imposition."]
                                          : ['peut_etre', "Ajoute l'avis d'imposition de tes parents pour l'estimer."];
    case 'contraception':
      return age !== null && age < 26 ? ['eligible', 'Tu as moins de 26 ans.'] : ['peut_etre', aide.conditions];
    case 'sante_psy':
    case 'transports':
    case 'repas_1_euro':
      return ['eligible', 'Accessible à tous les étudiants.'];
    default:
      return ['peut_etre', aide.conditions];
  }
}

return aides.map(aide => {
  const [eligibilite, raison] = evaluer(aide);
  const montant = aide.code === 'bourse_crous' || eligibilite === 'non_concerne' ? null : (aide.montant_max ?? null);
  return { json: {
    etudiant_id: p.etudiant_id,
    aide_code: aide.code,
    eligibilite,
    raison_eligibilite: raison,
    montant_estime: montant,
    niveau: aide.niveau,
    statut: 'proposee',
  } };
});

// Associe chaque document enregistré à sa photo (même ordre que le dépôt).
const photos = $('Vérifier et préparer').first().json.photos;
return $input.all().map((item, i) => ({ json: {
  document_id: item.json.id,
  etudiant_id: item.json.etudiant_id,
  nom_fichier: photos[i]?.nom_fichier || null,
  mime: photos[i]?.mime || null,
  contenu_base64: photos[i]?.base64 || '',
} })).filter(x => x.json.contenu_base64);
